func TestAssignUsesStableReplayIdentity(t *testing.T) {
	assigneeID := "user-support-1"
	ticketCapability := &assignTicketStub{
		locked:  schema.Ticket{ID: "ticket-3", UpdatedAt: "revision-3", AssigneeID: &assigneeID, Status: schema.TicketStatusInProgress, Title: "Email unavailable"},
		updated: schema.Ticket{ID: "ticket-3", UpdatedAt: "revision-3", AssigneeID: &assigneeID, Status: schema.TicketStatusInProgress, Title: "Email unavailable"},
	}
	notifications := &assignNotificationStub{}
	caps := capabilities.AssignCapabilities{
		Execution:     assignExecutionStub{principal: capabilities.Principal{UserID: "user-manager-1", SurfaceKey: "business_workspace", Known: true}, targetID: "ticket-3"},
		Ticket:        ticketCapability,
		Notifications: notifications,
	}
	input := capabilities.AssignInput{AssigneeID: assigneeID, RequestID: "request-replay-1"}

	for attempt := 0; attempt < 2; attempt++ {
		if _, err := Assign(t.Context(), caps, input); err != nil {
			t.Fatalf("replay attempt %d returned error: %v", attempt+1, err)
		}
	}
	if len(notifications.intents) != 2 {
		t.Fatalf("expected two staged replay intents for Runtime dedupe, got %d", len(notifications.intents))
	}
	for _, intent := range notifications.intents {
		if intent.SourceEventID != input.RequestID || intent.DedupeKey != input.RequestID || intent.SubjectVersion != "revision-3" {
			t.Fatalf("unstable replay identity: %#v", intent)
		}
	}
}
